function validate([source]) {
  if (!Array.isArray(source) || source.length < 1 || source.length > 100) return 'source needs 1 to 100 lines.';
  let inBlock = false;
  for (const text of source) {
    if (typeof text !== 'string' || text.length > 80) return 'Each line is a string of at most 80 characters.';
    for (let i = 0; i < text.length; i++) {
      const code = text.charCodeAt(i);
      if (code < 32 || code > 126) return 'Lines may contain only printable ASCII characters.';
      if (text[i] === '"' || text[i] === "'") return 'Lines may not contain quote characters.';
    }
    for (let i = 0; i < text.length; ) {
      const pair = text.slice(i, i + 2);
      if (inBlock) { if (pair === '*/') { inBlock = false; i += 2; } else i++; }
      else if (pair === '/*') { inBlock = true; i += 2; }
      else if (pair === '//') break;
      else i++;
    }
  }
  if (inBlock) return 'Every block comment must be closed.';
  return null;
}

