function removeComments(source) {
  // Work on the whole program as one string: a regex scan removes the earliest comment first,
  // block comments end at the first "*/" after their opening, and line comments stop at a newline.
  const whole = source.join('\n');
  const stripped = whole.replace(/\/\*[\s\S]*?\*\/|\/\/[^\n]*/g, '');
  return stripped.split('\n').filter(part => part.length > 0);
}

