function generate(rand, size) {
  const large = size === 'large';
  const lines = large ? 99 : 1 + Math.floor(rand() * 5);
  const maxLength = large ? 80 : 10;
  const tokens = ['/', '*', '/*', '*/', '//', '/*/', ' ', 'a', 'b', 'x;', '{', '}', '=', 'int', '(', ')'];
  const plain = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 ;,.(){}[]<>=+-*/!?#&|_%^~@$:`\\';
  const source = [];
  for (let l = 0; l < lines; l++) {
    const target = Math.floor(rand() * (maxLength + 1));
    let text = '';
    while (text.length < target) {
      const piece = rand() < 0.5 ? tokens[Math.floor(rand() * tokens.length)] : plain[Math.floor(rand() * plain.length)];
      if (text.length + piece.length > maxLength) break;
      text += piece;
    }
    source.push(text);
  }
  // Every block comment must be closed: if the scan ends inside one, add a closing line.
  let inBlock = false;
  for (const text of source) {
    for (let i = 0; i < text.length; ) {
      const pair = text.slice(i, i + 2);
      if (inBlock) { if (pair === '*/') { inBlock = false; i += 2; } else i++; }
      else if (pair === '/*') { inBlock = true; i += 2; }
      else if (pair === '//') break;
      else i++;
    }
  }
  if (inBlock) source.push('*/');
  return [source];
}
